<?php
namespace qqworld_collector\module\auto_save_attachments; use qqworld_collector\lib; class convert_file_format extends lib { var $options; var $log_id = 'cron-convert-file-format'; public function __construct() { add_action( 'wp_ajax_qqworld-collector-convert-file-format-scanning', array($this, 'scanning') ); add_action( 'wp_ajax_nopriv_qqworld-collector-convert-file-format-scanning', array($this, 'scanning') ); add_action( 'wp_ajax_qqworld-collector-convert-file-format-restart-scanning', array($this, 'restart_scanning') ); add_action( 'wp_ajax_nopriv_qqworld-collector-convert-file-format-restart-scanning', array($this, 'restart_scanning') ); add_action( 'wp_ajax_qqworld-collector-convert-file-format-schedule-scan', array($this, 'schedule_scan') ); add_action( 'wp_ajax_nopriv_qqworld-collector-convert-file-format-schedule-scan', array($this, 'schedule_scan') ); add_action( 'wp_ajax_qqworld-collector-convert-file-format-cancel-all-crons', array($this, 'cancel_schedule_scan') ); add_action( 'wp_ajax_nopriv_qqworld-collector-convert-file-format-cancel-all-crons', array($this, 'cancel_schedule_scan') ); add_action( 'qqworld-collector-auto-save-attachment-convert-schedule-scan', array($this, 'do_schedule_scan') ); add_filter( 'bulk_actions-upload', array($this, 'add_bulk_actions') ); add_filter( 'handle_bulk_actions-upload', array($this, 'handle_bulk_actions'), 10, 3 ); add_action( 'qqworld-collector-admin-notices-upload', array($this, 'admin_notices') ); add_filter( 'qqworld-collector-convert-file-format-to', array($this, 'convert_to'), 10, 3 ); } public function init() {} public function scanning() { extract($_POST); $exclude = get_option('qqworld-collector-convert-image-file-fromat-selected-images-exclude', array()); $exclude = $exclude ? $exclude : array(); foreach ($from as $mime_type) { for ($paged=0; $paged<=99999999; $paged++) { $args = array( 'post_type' => 'attachment', 'post_status' => 'inherit', 'post_mime_type' => $mime_type, 'posts_per_page' => 10, 'offset' => 10*$paged, 'exclude' => $exclude ); $posts = get_posts($args); if (!empty($posts)) { foreach ($posts as $post) { $this->convert_to($post->ID, $to); $exclude[] = $post->ID; } update_option('qqworld-collector-convert-image-file-fromat-selected-images-exclude', $exclude); } else { break; } } } $results = array( 'success' => 1 ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function restart_scanning() { update_option('qqworld-collector-convert-image-file-fromat-selected-images-exclude', array()); $results = array( 'success' => 1 ); print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function no_media_library_cancel_all_crons() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $crons = $this->get_crons('qqworld-collector-cloud-storage-no-media-library-schedule-scan'); if ($crons) foreach ($crons as $cron) { wp_clear_scheduled_hook( 'qqworld-collector-cloud-storage-no-media-library-schedule-scan', $cron['options']['args'] ); $results = array( 'success' => 1, 'msg' => __('Successfully canceled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('The task is not exists.', $this->text_domain) ); } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function convert_to($attachment_id, $format = 'webp', $action = 'override') { global $wpdb; $type = get_post_mime_type($attachment_id); switch ($type) { case 'image/avif': $source_type = 'avif'; $ext = 'avif'; break; case 'image/jpeg': $source_type = 'jpeg'; $ext = 'jpe?g'; break; case 'image/png': $source_type = 'png'; $ext = $source_type; break; case 'image/gif': $source_type = 'gif'; $ext = $source_type; break; case 'image/webp': $source_type = 'webp'; $ext = $source_type; break; case 'image/bmp': case 'image/x-ms-bmp': $source_type = 'bmp'; $ext = $source_type; break; default: $source_type = false; break; } if (!$source_type || $source_type == $format) return $attachment_id; $patterns = array(); $replacements = array(); $delete = array(); $converted = array(); $metadata = get_post_meta($attachment_id, '_wp_attachment_metadata', true); $filepath = get_attached_file( $attachment_id ); if (file_exists($filepath)) { $file = apply_filters( 'qqworld-collector-convert-file-format', file_get_contents($filepath), $source_type, $format ); if ( $file && apply_filters( 'qqworld-collector-convert-file-format-successed', false ) ) { $delete[] = $filepath; $filepath = preg_replace('/\.'.$ext.'$/i', '.'.$format, $filepath); $converted[] = $filepath; file_put_contents($filepath, $file); $patterns[] = $metadata['file']; $dirname = dirname($metadata['file']); $metadata['file'] = preg_replace('/\.'.$ext.'$/i', '.'.$format, $metadata['file']); $replacements[] = $metadata['file']; } else return $attachment_id; } $path = dirname($filepath); if (isset($metadata['sizes'])) { foreach ($metadata['sizes'] as $size => &$data) { $filepath = $path . DIRECTORY_SEPARATOR . $data['file']; if (file_exists($filepath)) { $file = apply_filters( 'qqworld-collector-convert-file-format', file_get_contents($filepath), $source_type, $format ); if ( $file && apply_filters( 'qqworld-collector-convert-file-format-successed', false ) ) { $delete[] = $filepath; $filepath = preg_replace('/\.'.$ext.'$/i', '.'.$format, $filepath); $converted[] = $filepath; file_put_contents($filepath, $file); $patterns[] = $dirname . '/' . $data['file']; $data['file'] = preg_replace('/\.'.$ext.'$/', '.'.$format, $data['file']); $replacements[] = $dirname . '/' . $data['file']; $data['mime-type'] = str_replace($source_type, $format, $data['mime-type']); } else return $attachment_id; } } } if ($action == 'override') { if ($this->options->cloud_storage_enabled) do_action( 'qqworld-collector-cloud-storage-delete-attachment', $attachment_id ); update_post_meta($attachment_id, '_wp_attachment_metadata', $metadata); if ($this->options->cloud_storage_enabled) do_action( 'qqworld-collector-cloud-storage-sync-single-attachment', $attachment_id ); $attached_file = get_post_meta($attachment_id, '_wp_attached_file', true); $attached_file = preg_replace('/\.'.$ext.'$/', '.'.$format, $attached_file); update_post_meta($attachment_id, '_wp_attached_file', $attached_file); $sql = $wpdb->prepare("SELECT `guid` FROM `{$wpdb->posts}` WHERE `ID` = %d LIMIT 1", $attachment_id); $result = $wpdb->get_row($sql); $wpdb->update( $wpdb->posts, array( 'post_mime_type' => 'image/' . $format, 'guid' => preg_replace('/\.'.$ext.'$/', '.'.$format, $result->guid) ), array( 'ID' => $attachment_id ), array( '%s', '%s'), array( '%d') ); foreach ($delete as $index => $del) if (file_exists($converted[$index]) && file_exists($del)) unlink($del); } else { $attached_file = get_post_meta($attachment_id, '_wp_attached_file', true); $attachment = get_post($attachment_id, ARRAY_A); unset($attachment['ID']); $attachment['post_mime_type'] = 'image/' . $format; $attachment['guid'] = preg_replace('/\.'.$ext.'$/', '.'.$format, $attachment['guid']); $attachment_id = wp_insert_post($attachment); update_post_meta($attachment_id, '_wp_attachment_metadata', $metadata); $attached_file = preg_replace('/\.'.$ext.'$/', '.'.$format, $attached_file); update_post_meta($attachment_id, '_wp_attached_file', $attached_file); } foreach ($patterns as $index => $pattern) { $sql = "UPDATE `{$wpdb->posts}` SET `post_content`=REPLACE(`post_content`, '{$pattern}', '{$replacements[$index]}')"; $result = $wpdb->query($sql); } return $attachment_id; } public function schedule_scan() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if ( !isset($_POST['recurrence']) || !isset($_POST['after']) ) exit; $mime_types = isset($_POST['mime_types']) && $_POST['mime_types'] ? $_POST['mime_types'] : ['image/jpeg']; $recurrence = $_POST['recurrence']; $after = intval( $_POST['after']); $offset = $after * 60; $args = array(array('mime_types' => $mime_types)); $timestamp = wp_next_scheduled( 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $args ); if ( !$timestamp ) { if ($recurrence) { $timestamp = wp_schedule_event( time()+$offset, $recurrence, 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $args ); } else { $timestamp = wp_schedule_single_event( time()+$offset, 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $args ); } if ($timestamp !== false) { $results = array( 'success' => 1, 'msg' => __('Successfully scheduled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('Scheduled failed.', $this->text_domain) ); } } else { if ($recurrence) { $timestamp = wp_reschedule_event( time()+$offset, $recurrence, 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $args ); } else { wp_clear_scheduled_hook( 'qqworld-collector-auto-save-attachment-convert-schedule-scan' ); $timestamp = wp_schedule_single_event( time()+$offset, 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $args ); } if ($timestamp !== false) { $results = array( 'success' => 1, 'msg' => __('The task is exists, already rescheduled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('The task is exists, rescheduled failed.', $this->text_domain) ); } } echo json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function cancel_schedule_scan() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $crons = $this->get_crons('qqworld-collector-auto-save-attachment-convert-schedule-scan'); if ($crons) foreach ($crons as $cron) { wp_clear_scheduled_hook( 'qqworld-collector-auto-save-attachment-convert-schedule-scan', $cron['options']['args'] ); $results = array( 'success' => 1, 'msg' => __('Successfully canceled.', $this->text_domain) ); } else { $results = array( 'success' => 0, 'msg' => __('The task is not exists.', $this->text_domain) ); } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function do_schedule_scan($args) { do_action( 'qqworld-collector-log', $this->log_id, __('Start the convert file format task. Arguments:', $this->text_domain), print_r($args, true), true ); $this->scanning(); do_action( 'qqworld-collector-log', $this->log_id, __('Finished the scan posts task.', $this->text_domain), '', true ); } public function add_bulk_actions($actions) { $actions['convert-to-webp'] = __('Convert to WEBP', $this->text_domain); $actions['convert-to-jpeg'] = __('Convert to JPEG', $this->text_domain); return $actions; } public function handle_bulk_actions( $redirect_to, $doaction, $post_ids ) { switch ($doaction) { case 'convert-to-webp': foreach ( $post_ids as $attachment_id ) { $this->convert_to($attachment_id, 'webp'); } $redirect_to = remove_query_arg( 'bulk_convert_to_jpeg', $redirect_to ); $redirect_to = add_query_arg( 'bulk_convert_to_webp', count( $post_ids ), $redirect_to ); break; case 'convert-to-jpeg': foreach ( $post_ids as $attachment_id ) { $this->convert_to($attachment_id, 'jpeg'); } $redirect_to = remove_query_arg( 'bulk_convert_to_webp', $redirect_to ); $redirect_to = add_query_arg( 'bulk_convert_to_jpeg', count( $post_ids ), $redirect_to ); break; } return $redirect_to; } public function admin_notices() { if ( ! empty( $_REQUEST['bulk_convert_to_webp'] ) ) { $hanler_count = intval( $_REQUEST['bulk_convert_to_webp'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Converted 1 attachment to WEBP format.', 'Converted %d attachments to WEBP format.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } if ( ! empty( $_REQUEST['bulk_convert_to_jpeg'] ) ) { $hanler_count = intval( $_REQUEST['bulk_convert_to_jpeg'] ); printf( '<div id="message" class="updated fade"><p>' . _n( 'Converted 1 attachment to JPEG format.', 'Converted %d attachments to JPEG format.', $hanler_count, $this->text_domain) . '</p></div>', $hanler_count ); } } } ?>